const { AgentClient } = require("agents/client");
const version = JSON.parse(require("fs").readFileSync("/w/node_modules/agents/package.json", "utf8")).version;
class FakeWS extends EventTarget {
  constructor(url) {
    super();
    this.url = url;
    this.readyState = 0;
    this.binaryType = "blob";
    this.protocol = "";
    this.extensions = "";
    this.bufferedAmount = 0;
    const msg = (data) => this.dispatchEvent(new MessageEvent("message", { data: JSON.stringify(data) }));
    setTimeout(() => {
      this.readyState = 1;
      this.dispatchEvent(new Event("open"));
      setTimeout(() => {
        msg({ type: "cf_agent_identity", name: "default", agent: "counter", stateFollows: true });
        setTimeout(() => msg({ type: "cf_agent_state", state: { count: 7 } }), 20);
      }, 10);
    }, 10);
  }
  send() {}
  close() { this.readyState = 3; }
}
FakeWS.CONNECTING = 0;
FakeWS.OPEN = 1;
FakeWS.CLOSING = 2;
FakeWS.CLOSED = 3;
let client;
try {
  client = new AgentClient({ agent: "counter", host: "localhost:8787", WebSocket: FakeWS });
} catch (e) {
  console.error("ERROR: AgentClient constructor threw: " + e.message);
  process.exit(2);
}
const timer = setTimeout(() => {
  console.error("ERROR: ready did not resolve within 5s");
  process.exit(2);
}, 5000);
client.ready.then(() => {
  clearTimeout(timer);
  const s = client.state;
  if (s && s.count === 7) {
    console.log("OK: agents " + version + " AgentClient ready resolved with state " + JSON.stringify(s));
    process.exit(0);
  }
  if (s === undefined) {
    console.error("FAIL: AgentClient ready resolved before the state frame; state was undefined");
    process.exit(1);
  }
  console.error("ERROR: unexpected state at ready: " + JSON.stringify(s));
  process.exit(2);
}, (e) => {
  console.error("ERROR: ready rejected: " + (e && e.message));
  process.exit(2);
});

